/* ═══════════════════════════════════════════════════════════
   NEXUS DUEL 24 — online room duel
   ═══════════════════════════════════════════════════════════ */

:root {
  --bg: #04060d;
  --ink: #eaf6ff;
  --muted: #7e93ab;
  --cyan: #43f0ff;
  --cyan-dim: rgba(67, 240, 255, 0.18);
  --magenta: #ff3df2;
  --violet: #8a5cff;
  --gold: #ffd166;
  --lime: #a8ff5f;
  --red: #ff4d6d;
  --panel: rgba(8, 14, 28, 0.78);
  --line: rgba(105, 190, 230, 0.16);
  --mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  --sans: "Segoe UI", "Hiragino Kaku Gothic ProN", "Noto Sans JP", system-ui, sans-serif;
  --zone-gap: 6px;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  overflow: hidden;
  color: var(--ink);
  background: var(--bg);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  text-rendering: optimizeLegibility;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  border: 0;
  background: none;
}
button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }
[hidden] { display: none !important; }

#bg {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

.bg-grid {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(67, 240, 255, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(67, 240, 255, 0.055) 1px, transparent 1px);
  background-size: 54px 54px;
  -webkit-mask-image: radial-gradient(ellipse at 50% 48%, #000 8%, transparent 74%);
  mask-image: radial-gradient(ellipse at 50% 48%, #000 8%, transparent 74%);
  animation: gridDrift 24s linear infinite;
}

@keyframes gridDrift {
  to { background-position: 54px 108px, 108px 54px; }
}

.bg-glow {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(600px 360px at 50% 42%, rgba(67, 240, 255, 0.10), transparent 70%),
    radial-gradient(520px 340px at 12% 88%, rgba(138, 92, 255, 0.12), transparent 70%),
    radial-gradient(460px 300px at 88% 12%, rgba(255, 61, 242, 0.09), transparent 70%),
    radial-gradient(900px 700px at 50% 120%, rgba(0, 20, 40, 0.65), transparent 70%);
}

/* ───────────────── boot ───────────────── */

.boot {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(700px 500px at 50% 40%, rgba(67, 240, 255, 0.09), transparent 70%),
    #03050b;
  transition: opacity 0.6s ease, visibility 0.6s ease;
}
.boot.gone { opacity: 0; visibility: hidden; }

.boot-panel {
  width: min(560px, 100%);
  padding: 34px clamp(20px, 5vw, 44px) 26px;
  border: 1px solid rgba(67, 240, 255, 0.22);
  border-radius: 4px;
  background: linear-gradient(160deg, rgba(9, 19, 34, 0.94), rgba(4, 8, 16, 0.96));
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.6), 0 40px 120px rgba(0, 0, 0, 0.7), inset 0 0 80px rgba(67, 240, 255, 0.04);
  position: relative;
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
}
.boot-panel::before,
.boot-panel::after {
  content: "";
  position: absolute;
  background: var(--cyan);
  opacity: 0.55;
}
.boot-panel::before { top: 0; left: 0; width: 120px; height: 1px; }
.boot-panel::after { bottom: 0; right: 0; width: 120px; height: 1px; }

.boot-mark {
  font-family: var(--mono);
  font-weight: 800;
  font-size: clamp(30px, 6.5vw, 48px);
  letter-spacing: 0.02em;
  line-height: 1;
  color: #fff;
  text-shadow: 0 0 26px rgba(67, 240, 255, 0.55);
}
.boot-mark span {
  color: var(--cyan);
  margin-left: 0.18em;
  text-shadow: 0 0 20px rgba(67, 240, 255, 0.8);
}
.boot-mark em {
  font-style: normal;
  font-size: 0.48em;
  vertical-align: super;
  color: var(--gold);
  margin-left: 0.25em;
  letter-spacing: 0.1em;
}

.boot-tag {
  margin-top: 10px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.34em;
  color: var(--muted);
}

.boot-log {
  margin: 30px 0 22px;
  min-height: 156px;
  font-family: var(--mono);
  font-size: 11px;
  line-height: 2;
  color: #9fb8cf;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.boot-line { animation: bootLine 0.28s ease both; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.boot-line b { color: var(--lime); font-weight: 500; margin-right: 8px; }
.boot-line.hot b { color: var(--gold); }
.boot-line.hot { color: #fff; text-shadow: 0 0 12px rgba(255, 209, 102, 0.5); }
@keyframes bootLine {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: none; }
}

.boot-track {
  height: 3px;
  background: rgba(67, 240, 255, 0.1);
  overflow: hidden;
}
.boot-track i {
  display: block;
  width: 0;
  height: 100%;
  background: linear-gradient(90deg, var(--violet), var(--cyan));
  box-shadow: 0 0 14px var(--cyan);
  transition: width 0.35s ease;
}

.boot-foot {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.18em;
  color: #5c7188;
}

/* ───────────────── app shell ───────────────── */

.app {
  position: relative;
  z-index: 2;
  height: 100vh;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  opacity: 0;
  transition: opacity 0.7s ease;
}
.app.on { opacity: 1; }

.topbar {
  flex: 0 0 auto;
  height: 58px;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0 16px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(9, 16, 30, 0.92), rgba(5, 9, 18, 0.66));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }
.brand-mark {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  font-family: var(--mono);
  font-weight: 900;
  font-size: 18px;
  color: #031018;
  background: linear-gradient(145deg, var(--cyan), #9dffdf);
  box-shadow: 0 0 18px rgba(67, 240, 255, 0.5);
  clip-path: polygon(0 0, 100% 0, 100% 72%, 72% 100%, 0 100%);
}
.brand-text { display: flex; flex-direction: column; line-height: 1.05; }
.brand-text b {
  font-family: var(--mono);
  font-size: 14px;
  letter-spacing: 0.16em;
  white-space: nowrap;
}
.brand-text small {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.28em;
  color: var(--muted);
  margin-top: 4px;
  white-space: nowrap;
}
.brand-badge {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  color: var(--gold);
  border: 1px solid rgba(255, 209, 102, 0.35);
  padding: 3px 5px;
  border-radius: 3px;
  transform: translateY(-6px);
}

.room-status {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  padding: 7px 12px;
  border: 1px solid rgba(67, 240, 255, 0.16);
  border-radius: 999px;
  background: rgba(6, 12, 24, 0.7);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  white-space: nowrap;
  color: var(--muted);
}
.room-status b { color: var(--cyan); font-size: 11px; }
.room-label { color: #9fb4c9; }
.room-state {
  color: var(--lime);
  border-left: 1px solid var(--line);
  padding-left: 8px;
  font-size: 9px;
}

.live-dot {
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 8px var(--lime);
  animation: livePulse 1.8s ease-in-out infinite;
}
@keyframes livePulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

.top-actions { display: flex; align-items: center; gap: 7px; }
.net {
  display: flex;
  align-items: baseline;
  gap: 2px;
  margin-right: 4px;
  font-family: var(--mono);
  color: #9fb4c9;
  font-size: 11px;
}
.net small { font-size: 8px; color: var(--muted); }

.icon-btn {
  min-width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 8px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  color: #a9c2d8;
  border: 1px solid rgba(105, 190, 230, 0.18);
  border-radius: 6px;
  background: rgba(8, 16, 30, 0.7);
  transition: color 0.2s, border-color 0.2s, box-shadow 0.2s, transform 0.2s;
}
.icon-btn:hover { color: var(--cyan); border-color: rgba(67, 240, 255, 0.5); box-shadow: 0 0 16px rgba(67, 240, 255, 0.15); transform: translateY(-1px); }
.icon-btn.off { color: #51657a; border-color: rgba(105, 190, 230, 0.1); }
.mobile-only { display: none; }

.shell {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr) 238px;
  gap: 12px;
  padding: 10px 14px 0;
}

/* ───────────────── panels ───────────────── */

.panel {
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(8, 15, 29, 0.82), rgba(5, 9, 19, 0.62));
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  color: #b9d2e8;
}
.panel-head .live-dot { margin-left: auto; }
.tiny-btn {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: var(--cyan);
  padding: 3px 6px;
  border: 1px solid rgba(67, 240, 255, 0.25);
  border-radius: 3px;
  transition: background 0.2s, box-shadow 0.2s;
}
.tiny-btn:hover { background: rgba(67, 240, 255, 0.1); box-shadow: 0 0 12px rgba(67, 240, 255, 0.2); }

.panel-sub {
  display: flex;
  justify-content: space-between;
  margin: 5px 0 10px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: #5f758c;
}
.panel-sub span:last-child { color: var(--cyan); }

.rooms { flex: 1 1 auto; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 7px; padding-right: 2px; }
.rooms::-webkit-scrollbar, .feed::-webkit-scrollbar, .hand-scroll::-webkit-scrollbar { width: 4px; height: 4px; }
.rooms::-webkit-scrollbar-thumb, .feed::-webkit-scrollbar-thumb, .hand-scroll::-webkit-scrollbar-thumb { background: rgba(67, 240, 255, 0.2); border-radius: 4px; }

.room {
  position: relative;
  padding: 8px 9px;
  border: 1px solid rgba(105, 190, 230, 0.12);
  border-radius: 7px;
  background: rgba(7, 13, 26, 0.65);
  font-family: var(--mono);
  transition: border-color 0.25s, background 0.25s;
}
.room:hover { border-color: rgba(67, 240, 255, 0.28); }
.room.mine {
  border-color: rgba(67, 240, 255, 0.42);
  background: linear-gradient(100deg, rgba(67, 240, 255, 0.11), rgba(138, 92, 255, 0.05));
  box-shadow: inset 3px 0 0 var(--cyan), 0 0 22px rgba(67, 240, 255, 0.07);
}
.room.mine::after {
  content: "AUTO-JOINED";
  position: absolute;
  top: -1px;
  right: -1px;
  padding: 2px 5px;
  font-size: 6px;
  letter-spacing: 0.12em;
  color: #041018;
  background: var(--cyan);
  border-radius: 0 6px 0 6px;
}
.room-top { display: flex; align-items: center; gap: 6px; }
.room-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 7px currentColor; flex: 0 0 auto; }
.room-dot.open { color: var(--lime); background: var(--lime); }
.room-dot.duel { color: var(--magenta); background: var(--magenta); animation: livePulse 1.4s infinite; }
.room-dot.full { color: #ff9f43; background: #ff9f43; }
.room-top b { font-size: 10px; font-weight: 600; letter-spacing: 0.05em; color: #dcecf9; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.room-players { margin-left: auto; font-size: 8px; color: var(--muted); }
.room-bottom { display: flex; align-items: center; gap: 8px; margin-top: 5px; font-size: 7px; letter-spacing: 0.05em; color: #647d95; }
.room-bottom .pill { margin-left: auto; color: #8aa4bb; border: 1px solid rgba(105, 190, 230, 0.15); padding: 1px 4px; border-radius: 2px; }
.room.mine .room-bottom .pill { color: var(--lime); border-color: rgba(168, 255, 95, 0.25); }

.room-note {
  margin-top: 9px;
  padding: 7px 8px;
  display: flex;
  gap: 7px;
  align-items: flex-start;
  font-family: var(--mono);
  font-size: 7px;
  line-height: 1.7;
  letter-spacing: 0.04em;
  color: #6f879e;
  border: 1px dashed rgba(105, 190, 230, 0.14);
  border-radius: 5px;
}
.room-note .live-dot { margin-top: 2px; }

.net-card {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  margin-top: 9px;
  padding-top: 8px;
  border-top: 1px solid rgba(105, 190, 230, 0.1);
  font-family: var(--mono);
}
.net-card div { display: flex; flex-direction: column; gap: 3px; }
.net-card span { font-size: 6px; letter-spacing: 0.12em; color: #586e84; }
.net-card b { font-size: 8px; color: #a9c2d8; font-weight: 500; }

/* ───────────────── arena ───────────────── */

.arena-wrap {
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  overflow: hidden;
}

.arena {
  width: min(100%, 600px, 66vh);
  display: flex;
  flex-direction: column;
  gap: 5px;
  user-select: none;
  -webkit-user-select: none;
}

.side {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 6px;
  border-radius: 12px;
  border: 1px solid transparent;
}
.enemy-side {
  border-color: rgba(255, 61, 242, 0.13);
  background: linear-gradient(180deg, rgba(255, 61, 242, 0.035), transparent 70%);
}
.player-side {
  border-color: rgba(67, 240, 255, 0.14);
  background: linear-gradient(0deg, rgba(67, 240, 255, 0.04), transparent 70%);
}

.duelist {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 43px;
  padding: 5px 8px;
  border: 1px solid rgba(105, 190, 230, 0.14);
  border-radius: 9px;
  background: linear-gradient(100deg, rgba(8, 16, 31, 0.9), rgba(6, 11, 22, 0.6));
  position: relative;
  transition: box-shadow 0.25s, border-color 0.25s;
}
.enemy { border-color: rgba(255, 61, 242, 0.16); }
.player { border-color: rgba(67, 240, 255, 0.2); }
.player.targetable {
  cursor: crosshair;
  border-color: rgba(255, 209, 102, 0.7);
  box-shadow: 0 0 0 1px rgba(255, 209, 102, 0.2), 0 0 26px rgba(255, 209, 102, 0.16);
  animation: targetPulse 1.15s ease-in-out infinite;
}

.avatar {
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  font-family: var(--mono);
  font-weight: 800;
  font-size: 12px;
  clip-path: polygon(0 0, 100% 0, 100% 74%, 74% 100%, 0 100%);
  position: relative;
}
.enemy-avatar { color: #1a0017; background: linear-gradient(140deg, var(--magenta), #ff9f43); box-shadow: 0 0 16px rgba(255, 61, 242, 0.35); }
.player-avatar { color: #001318; background: linear-gradient(140deg, var(--cyan), #9dffdf); box-shadow: 0 0 16px rgba(67, 240, 255, 0.4); }

.duelist-info { flex: 1; min-width: 0; }
.duelist-top { display: flex; align-items: center; gap: 6px; margin-bottom: 4px; }
.duelist-top b { font-family: var(--mono); font-size: 10px; letter-spacing: 0.12em; }
.duelist-top span { font-family: var(--mono); font-size: 7px; color: var(--gold); letter-spacing: 0.08em; }
.duelist-top em { margin-left: auto; font-family: var(--mono); font-style: normal; font-size: 6px; letter-spacing: 0.18em; color: #5e748a; }

.lp-bar {
  position: relative;
  height: 15px;
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid rgba(105, 190, 230, 0.18);
  background: rgba(2, 7, 14, 0.92);
  transition: box-shadow 0.25s;
}
.lp-bar i {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  border-radius: 999px;
  transition: width 0.55s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.4s;
}
.player-lp i { background: linear-gradient(90deg, #0d8fa8, var(--cyan)); box-shadow: 0 0 14px rgba(67, 240, 255, 0.6); }
.enemy-lp i { background: linear-gradient(90deg, #a01887, var(--magenta)); box-shadow: 0 0 14px rgba(255, 61, 242, 0.55); }
.lp-bar span {
  position: absolute;
  left: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--mono);
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.05em;
  color: #fff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
  z-index: 1;
}
.lp-bar small { position: absolute; right: 7px; top: 50%; transform: translateY(-50%); font-family: var(--mono); font-size: 6px; letter-spacing: 0.12em; color: rgba(255, 255, 255, 0.55); z-index: 1; }
.lp-bar.danger { box-shadow: 0 0 18px rgba(255, 77, 109, 0.7); animation: dangerPulse 0.9s ease-in-out infinite; }
.lp-bar.danger i { background: linear-gradient(90deg, #7d0b20, var(--red)); }
.lp-bar.hit { animation: lpHit 0.35s ease; }
@keyframes dangerPulse { 50% { box-shadow: 0 0 28px rgba(255, 77, 109, 1); } }
@keyframes lpHit {
  20% { transform: translateX(-2px) scaleX(1.01); }
  45% { transform: translateX(2px); }
  70% { transform: translateX(-1px); }
}

.hand-dots { display: flex; gap: 2px; align-items: center; opacity: 0.55; }
.hand-dots i { width: 3px; height: 9px; border-radius: 1px; background: currentColor; }
.enemy .hand-dots { color: var(--magenta); }
.player .hand-dots { color: var(--cyan); }

.zone-row {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: var(--zone-gap);
}

.zone {
  position: relative;
  aspect-ratio: 5 / 6;
  border-radius: 7px;
  border: 1px dashed rgba(105, 190, 230, 0.16);
  background:
    linear-gradient(145deg, rgba(67, 240, 255, 0.025), transparent 55%),
    rgba(4, 9, 18, 0.5);
  display: grid;
  place-items: center;
  overflow: hidden;
  transition: border-color 0.2s, background 0.2s, box-shadow 0.2s, transform 0.2s;
}
.zone::after {
  content: "";
  position: absolute;
  inset: -100% 0 auto;
  height: 60%;
  background: linear-gradient(180deg, transparent, rgba(67, 240, 255, 0.05), transparent);
  animation: zoneScan 5.5s linear infinite;
  pointer-events: none;
}
@keyframes zoneScan { to { transform: translateY(360%); } }

.zone.back-row { border-color: rgba(138, 92, 255, 0.15); }
.zone-index {
  position: absolute;
  top: 4px;
  left: 5px;
  font-family: var(--mono);
  font-size: 6px;
  color: rgba(105, 190, 230, 0.34);
}
.zone-label {
  font-family: var(--mono);
  font-size: clamp(5px, 0.55vw, 7px);
  letter-spacing: 0.14em;
  color: rgba(105, 190, 230, 0.26);
  writing-mode: vertical-rl;
}
.zone.playable {
  border-color: rgba(67, 240, 255, 0.65);
  background: rgba(67, 240, 255, 0.06);
  box-shadow: inset 0 0 18px rgba(67, 240, 255, 0.10), 0 0 12px rgba(67, 240, 255, 0.12);
  cursor: pointer;
  animation: playablePulse 1.3s ease-in-out infinite;
}
.zone.playable .zone-label { color: var(--cyan); }
.zone.targetable {
  border-color: rgba(255, 209, 102, 0.8);
  background: rgba(255, 209, 102, 0.07);
  box-shadow: inset 0 0 16px rgba(255, 209, 102, 0.12), 0 0 14px rgba(255, 209, 102, 0.18);
  cursor: crosshair;
  animation: targetPulse 1.15s ease-in-out infinite;
}
.zone.filled { border-style: solid; border-color: transparent; background: transparent; }
.zone.filled::after { display: none; }
@keyframes playablePulse {
  50% { border-color: rgba(67, 240, 255, 1); box-shadow: inset 0 0 22px rgba(67, 240, 255, 0.2), 0 0 18px rgba(67, 240, 255, 0.2); }
}
@keyframes targetPulse {
  50% { border-color: rgba(255, 209, 102, 1); box-shadow: inset 0 0 20px rgba(255, 209, 102, 0.2), 0 0 22px rgba(255, 209, 102, 0.3); }
}

/* ───────────────── cards ───────────────── */

.card {
  position: relative;
  width: 100%;
  height: 100%;
  container-type: inline-size;
  border-radius: 7px;
  cursor: pointer;
  transform: translateZ(0);
}
.card-frame {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 5cqi 5cqi 4cqi;
  overflow: hidden;
  border-radius: inherit;
  border: 1px solid hsl(var(--hue) 90% 62% / 0.55);
  background:
    radial-gradient(90% 60% at 50% 18%, hsl(var(--hue) 90% 55% / 0.20), transparent 65%),
    linear-gradient(165deg, hsl(var(--hue) 55% 13% / 0.97), #060b16 72%);
  box-shadow:
    inset 0 0 18px hsl(var(--hue) 100% 60% / 0.10),
    0 3px 12px rgba(0, 0, 0, 0.5),
    0 0 12px hsl(var(--hue) 100% 60% / 0.12);
  animation: cardFloat 3.8s ease-in-out infinite;
  animation-delay: var(--delay, 0s);
  transition: box-shadow 0.25s, border-color 0.25s, filter 0.25s;
  will-change: transform;
}
.card-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, transparent 20%, hsl(var(--hue) 100% 80% / 0.10) 48%, transparent 62%);
  transform: translateX(-120%);
  animation: cardSheen 5.5s ease-in-out infinite;
  animation-delay: var(--delay, 0s);
  pointer-events: none;
}
.card-frame::after {
  content: "";
  position: absolute;
  inset: 2px;
  border: 1px solid hsl(var(--hue) 90% 70% / 0.16);
  border-radius: 4px;
  pointer-events: none;
}
@keyframes cardFloat {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  35% { transform: translateY(-1.8px) rotate(0.35deg); }
  70% { transform: translateY(0.9px) rotate(-0.25deg); }
}
@keyframes cardSheen {
  0%, 58% { transform: translateX(-120%); }
  82%, 100% { transform: translateX(140%); }
}

.card.spell .card-frame {
  border-style: solid;
  background:
    radial-gradient(90% 70% at 50% 25%, hsl(var(--hue) 90% 55% / 0.26), transparent 66%),
    linear-gradient(165deg, hsl(var(--hue) 50% 12% / 0.98), #080713 74%);
}
.card.monster .card-frame { border-bottom-color: hsl(var(--hue) 95% 66% / 0.9); }
.card.played .card-frame { animation: cardDeploy 0.55s cubic-bezier(0.18, 0.9, 0.25, 1.2) both, cardFloat 3.8s ease-in-out 0.55s infinite; }
@keyframes cardDeploy {
  0% { opacity: 0; transform: scale(0.55) translateY(-10px); filter: brightness(2.2); }
  60% { opacity: 1; transform: scale(1.05); filter: brightness(1.25); }
  100% { opacity: 1; transform: scale(1); filter: none; }
}
.card.spent .card-frame { filter: saturate(0.45) brightness(0.72); }

.card-head { display: flex; align-items: flex-start; gap: 2cqi; position: relative; z-index: 1; }
.card-name {
  flex: 1;
  min-width: 0;
  font-family: var(--mono);
  font-weight: 700;
  font-size: clamp(6px, 8.7cqi, 12px);
  line-height: 1.1;
  letter-spacing: 0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #f4fbff;
  text-shadow: 0 0 8px hsl(var(--hue) 100% 70% / 0.5);
}
.card-cost {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  min-width: 12cqi;
  height: 12cqi;
  max-width: 17px;
  max-height: 17px;
  font-family: var(--mono);
  font-size: clamp(6px, 8cqi, 10px);
  font-weight: 700;
  color: #041016;
  background: hsl(var(--hue) 95% 68%);
  border-radius: 3px;
  box-shadow: 0 0 8px hsl(var(--hue) 100% 60% / 0.7);
}
.card-art {
  position: relative;
  flex: 1;
  min-height: 0;
  margin: 3cqi 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 4px;
  background:
    radial-gradient(circle at 50% 42%, hsl(var(--hue) 100% 62% / 0.24), transparent 62%),
    repeating-linear-gradient(0deg, transparent 0 7px, hsl(var(--hue) 100% 60% / 0.055) 7px 8px),
    rgba(1, 5, 12, 0.55);
  border: 1px solid hsl(var(--hue) 90% 60% / 0.16);
}
.card-art::before {
  content: "";
  position: absolute;
  width: 65%;
  aspect-ratio: 1;
  border: 1px solid hsl(var(--hue) 100% 65% / 0.25);
  border-radius: 50%;
  animation: artRing 8s linear infinite;
}
.card-art::after {
  content: "";
  position: absolute;
  width: 44%;
  aspect-ratio: 1;
  border: 1px dashed hsl(var(--hue) 100% 65% / 0.22);
  border-radius: 50%;
  animation: artRing 5s linear infinite reverse;
}
@keyframes artRing { to { transform: rotate(360deg); } }
.card-glyph {
  position: relative;
  z-index: 1;
  font-size: clamp(15px, 31cqi, 38px);
  line-height: 1;
  filter: drop-shadow(0 0 9px hsl(var(--hue) 100% 65% / 0.75));
  animation: glyphPulse 2.6s ease-in-out infinite;
  animation-delay: var(--delay, 0s);
}
@keyframes glyphPulse {
  50% { transform: scale(1.07); filter: drop-shadow(0 0 15px hsl(var(--hue) 100% 70% / 0.95)); }
}

.card-foot { display: flex; align-items: flex-end; gap: 2cqi; position: relative; z-index: 1; }
.card-stat {
  display: flex;
  align-items: baseline;
  gap: 1.2cqi;
  font-family: var(--mono);
  font-weight: 700;
  font-size: clamp(6px, 8.5cqi, 11px);
  line-height: 1;
}
.card-stat small { font-size: 0.62em; font-weight: 400; letter-spacing: 0.06em; color: #7f95aa; }
.card-stat.atk { color: #ffd98a; }
.card-stat.def { margin-left: auto; color: #9fd6ff; }
.card-type {
  position: absolute;
  left: 5cqi;
  bottom: 5cqi;
  font-family: var(--mono);
  font-size: clamp(4px, 5cqi, 6px);
  letter-spacing: 0.14em;
  color: hsl(var(--hue) 90% 70% / 0.8);
  z-index: 1;
}
.card-desc {
  position: relative;
  z-index: 1;
  margin-top: 2cqi;
  font-size: clamp(4px, 5cqi, 7px);
  line-height: 1.35;
  color: #90a5ba;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* board cards: hide the description, keep stats */
.card--board .card-desc { display: none; }
.card--board .card-type { display: none; }
.card--board .card-frame { padding: 4cqi 4cqi 3cqi; }
.card--board .card-name { font-size: clamp(5px, 8.6cqi, 10px); }
.card--board .card-glyph { font-size: clamp(13px, 30cqi, 30px); }
.card--board .card-foot { margin-top: auto; }

.card.selected .card-frame {
  border-color: var(--gold);
  box-shadow: 0 0 0 1px rgba(255, 209, 102, 0.35), 0 0 26px rgba(255, 209, 102, 0.4), inset 0 0 20px rgba(255, 209, 102, 0.12);
  filter: brightness(1.16);
}
.card.selectable .card-frame { cursor: pointer; }
.card.attacked .card-frame { filter: saturate(0.6) brightness(0.68); }
.card.attacked::after {
  content: "USED";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-12deg);
  font-family: var(--mono);
  font-size: clamp(5px, 7cqi, 8px);
  letter-spacing: 0.14em;
  color: rgba(255, 255, 255, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.25);
  padding: 1px 3px;
  border-radius: 2px;
  pointer-events: none;
  z-index: 3;
}
.card.lunge { z-index: 10; }
.card.lunge .card-frame { animation: attackLunge 0.45s cubic-bezier(0.3, 0.9, 0.3, 1) both; }
.card.enemy-lunge .card-frame { animation: attackLungeDown 0.45s cubic-bezier(0.3, 0.9, 0.3, 1) both; }
@keyframes attackLunge {
  0% { transform: translateY(0) scale(1); }
  40% { transform: translateY(-9px) scale(1.06); filter: brightness(1.5); }
  100% { transform: translateY(0) scale(1); }
}
@keyframes attackLungeDown {
  0% { transform: translateY(0) scale(1); }
  40% { transform: translateY(9px) scale(1.06); filter: brightness(1.5); }
  100% { transform: translateY(0) scale(1); }
}
.card.hit .card-frame { animation: cardHit 0.4s ease both; }
@keyframes cardHit {
  0% { filter: brightness(2); transform: translateX(0); }
  25% { transform: translateX(-4px) rotate(-2deg); }
  50% { transform: translateX(4px) rotate(2deg); }
  100% { filter: none; transform: none; }
}
.card.destroyed .card-frame { animation: cardDestroy 0.4s ease both; }
@keyframes cardDestroy {
  to { opacity: 0; transform: scale(0.4) rotate(8deg); filter: brightness(3) blur(3px); }
}

/* ───────────────── hand ───────────────── */

.handbar {
  flex: 0 0 auto;
  height: clamp(136px, 18vh, 168px);
  display: flex;
  align-items: stretch;
  gap: 14px;
  padding: 6px 18px 10px;
  border-top: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(6, 11, 23, 0.5), rgba(7, 13, 26, 0.92));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  position: relative;
}
.handbar::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 42%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--cyan), transparent);
  opacity: 0.5;
}

.deck-zone { flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; width: 62px; }
.deck-zone small { font-family: var(--mono); font-size: 7px; letter-spacing: 0.16em; color: #5e748a; }
.deck-stack {
  position: relative;
  width: 42px;
  height: 56px;
  border: 1px solid rgba(67, 240, 255, 0.38);
  border-radius: 4px;
  background:
    repeating-linear-gradient(45deg, rgba(67, 240, 255, 0.09) 0 3px, transparent 3px 7px),
    linear-gradient(145deg, #0a1a2c, #050b16);
  box-shadow: 0 0 14px rgba(67, 240, 255, 0.14);
}
.deck-stack i {
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(67, 240, 255, 0.18);
  border-radius: 2px;
}
.deck-stack i:nth-child(2) { inset: 5px; }
.deck-stack i:nth-child(3) { inset: 7px; }
.deck-stack span {
  position: absolute;
  bottom: 3px;
  right: 4px;
  z-index: 2;
  font-family: var(--mono);
  font-weight: 700;
  font-size: 10px;
  color: var(--cyan);
  text-shadow: 0 0 8px rgba(67, 240, 255, 0.9);
}
.deck-stack::after {
  content: "NEXUS";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-90deg);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.28em;
  color: rgba(67, 240, 255, 0.5);
  z-index: 3;
}

.hand-scroll { flex: 1 1 auto; min-width: 0; overflow-x: auto; overflow-y: hidden; display: flex; align-items: flex-end; padding: 10px 6px 2px; }
.hand { display: flex; align-items: flex-end; justify-content: center; gap: 7px; margin: 0 auto; min-height: 100%; }
.hand-empty {
  align-self: center;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  color: #536a80;
  border: 1px dashed rgba(105, 190, 230, 0.16);
  padding: 12px 18px;
  border-radius: 6px;
}

.hand-card {
  flex: 0 0 auto;
  width: clamp(74px, 7.4vw, 104px);
  aspect-ratio: 5 / 7;
  position: relative;
  transform-origin: 50% 100%;
  transition: transform 0.24s cubic-bezier(0.2, 0.8, 0.2, 1), filter 0.24s;
  animation: handIn 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.15) both;
  animation-delay: calc(var(--i, 0) * 30ms);
}
@keyframes handIn {
  from { opacity: 0; transform: translateY(26px) scale(0.9); }
  to { opacity: 1; transform: none; }
}
.hand-card:hover { transform: translateY(-10px) scale(1.035); z-index: 5; filter: brightness(1.1); }
.hand-card.selected { transform: translateY(-14px) scale(1.055); z-index: 6; }
.hand-card.selected .card-frame { border-color: var(--gold); box-shadow: 0 0 0 1px rgba(255, 209, 102, 0.4), 0 0 30px rgba(255, 209, 102, 0.45); }
.hand-card.dim { filter: saturate(0.5) brightness(0.6); }
.hand-card .card-frame { animation-duration: 4.6s; }
.hand-card .card-desc { font-size: clamp(4px, 5.4cqi, 7px); }
.hand-card .card-art { margin: 3cqi 0; }
.hand-key {
  position: absolute;
  bottom: -4px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--mono);
  font-size: 6px;
  color: #5e748a;
  z-index: 2;
}

.hand-side {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
  width: 106px;
}
.turn-mini { font-family: var(--mono); font-size: 8px; letter-spacing: 0.14em; color: #5e748a; text-align: center; }
.turn-mini b { color: #b9d2e8; font-size: 11px; }

.action-btn {
  font-family: var(--mono);
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.14em;
  color: #021014;
  background: linear-gradient(120deg, var(--cyan), #9dffdf);
  padding: 10px 18px;
  border-radius: 5px;
  box-shadow: 0 0 20px rgba(67, 240, 255, 0.3);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%);
  transition: transform 0.18s, box-shadow 0.18s, opacity 0.2s;
  white-space: nowrap;
}
.action-btn:hover:not(:disabled) { transform: translateY(-1px); box-shadow: 0 0 30px rgba(67, 240, 255, 0.55); }
.action-btn:active:not(:disabled) { transform: translateY(1px); }
.action-btn:disabled { opacity: 0.3; box-shadow: none; cursor: not-allowed; }
.action-btn.small { padding: 9px 12px; font-size: 9px; width: 100%; }
.action-btn.ready { animation: btnReady 1.6s ease-in-out infinite; }
@keyframes btnReady {
  50% { box-shadow: 0 0 34px rgba(67, 240, 255, 0.65); }
}

.ghost-btn {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  color: #a9c2d8;
  padding: 9px 14px;
  border: 1px solid rgba(105, 190, 230, 0.3);
  border-radius: 4px;
  background: rgba(8, 16, 30, 0.6);
  transition: color 0.2s, border-color 0.2s, background 0.2s;
}
.ghost-btn:hover { color: var(--cyan); border-color: var(--cyan); background: rgba(67, 240, 255, 0.08); }
.ghost-btn.small { padding: 6px 9px; font-size: 8px; }

/* ───────────────── midline ───────────────── */

.midline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 42px;
  padding: 2px 8px;
  position: relative;
}
.midline::before {
  content: "";
  position: absolute;
  left: 4%;
  right: 4%;
  top: 50%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(67, 240, 255, 0.28), rgba(255, 61, 242, 0.28), transparent);
  z-index: 0;
}
.turn-chip {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border: 1px solid rgba(67, 240, 255, 0.36);
  border-radius: 3px;
  background: rgba(4, 10, 20, 0.92);
  font-family: var(--mono);
  box-shadow: 0 0 18px rgba(67, 240, 255, 0.14);
  transition: border-color 0.3s, box-shadow 0.3s;
}
.turn-chip b { font-size: 9px; letter-spacing: 0.1em; color: var(--cyan); }
.turn-chip small { font-size: 6px; letter-spacing: 0.1em; color: #60778d; }
.turn-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); animation: livePulse 1.5s infinite; }
.turn-chip.enemy { border-color: rgba(255, 61, 242, 0.4); box-shadow: 0 0 18px rgba(255, 61, 242, 0.16); }
.turn-chip.enemy b { color: var(--magenta); }
.turn-chip.enemy .turn-dot { background: var(--magenta); box-shadow: 0 0 8px var(--magenta); }
.turn-chip.over { border-color: rgba(255, 209, 102, 0.4); }
.turn-chip.over b { color: var(--gold); }
.turn-chip.over .turn-dot { background: var(--gold); box-shadow: 0 0 8px var(--gold); }

.field-tag {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.16em;
  color: #52687e;
  white-space: nowrap;
}
.field-tag span { width: 14px; height: 1px; background: rgba(105, 190, 230, 0.3); }

.ap-wrap { position: relative; z-index: 1; display: flex; align-items: center; gap: 6px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.12em; color: #60778d; }
.ap-pips { display: flex; gap: 3px; }
.pip {
  width: 12px;
  height: 5px;
  border-radius: 1px;
  background: rgba(67, 240, 255, 0.12);
  border: 1px solid rgba(67, 240, 255, 0.22);
  transition: background 0.2s, box-shadow 0.2s;
}
.pip.on { background: var(--cyan); box-shadow: 0 0 8px rgba(67, 240, 255, 0.7); border-color: var(--cyan); }
.pip.spent { background: rgba(67, 240, 255, 0.04); }

.controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: min(100%, 600px);
  min-height: 34px;
  padding: 0 4px;
}
.hint {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: #6f879e;
  text-align: center;
  transition: color 0.2s;
}
.hint.hot { color: var(--gold); }
.hint.cool { color: var(--cyan); }

/* ───────────────── feed ───────────────── */

.feed {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 8px 0;
  padding-right: 2px;
}
.feed-item {
  display: grid;
  grid-template-columns: 36px 1fr;
  gap: 5px;
  padding: 4px 5px;
  border-radius: 3px;
  border-left: 2px solid rgba(105, 190, 230, 0.2);
  background: rgba(7, 13, 26, 0.45);
  animation: feedIn 0.3s ease both;
}
@keyframes feedIn { from { opacity: 0; transform: translateX(6px); } to { opacity: 1; transform: none; } }
.feed-item time { font-family: var(--mono); font-size: 6px; color: #536a80; padding-top: 2px; }
.feed-item p { margin: 0; font-family: var(--mono); font-size: 7.5px; line-height: 1.5; color: #9db4c9; word-break: break-word; }
.feed-item.you { border-left-color: var(--cyan); }
.feed-item.you p { color: #b6ecf4; }
.feed-item.enemy { border-left-color: var(--magenta); }
.feed-item.enemy p { color: #f3b9ef; }
.feed-item.battle { border-left-color: var(--gold); }
.feed-item.battle p { color: #ffe1a0; }
.feed-item.win { border-left-color: var(--lime); background: rgba(168, 255, 95, 0.06); }
.feed-item.win p { color: var(--lime); }
.feed-item.sys p { color: #748ba1; }

.hand-info {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  padding-top: 8px;
  border-top: 1px solid rgba(105, 190, 230, 0.1);
}
.hand-info div { display: flex; flex-direction: column; align-items: center; gap: 3px; font-family: var(--mono); }
.hand-info span { font-size: 6px; letter-spacing: 0.12em; color: #586e84; }
.hand-info b { font-size: 12px; color: var(--cyan); }

/* ───────────────── overlays ───────────────── */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 22px;
  background: rgba(2, 5, 12, 0.82);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.35s, visibility 0.35s;
}
.overlay.on { opacity: 1; visibility: visible; pointer-events: auto; }

.result-card, .rules-card {
  width: min(460px, 100%);
  padding: 30px clamp(20px, 5vw, 38px) 28px;
  border: 1px solid rgba(67, 240, 255, 0.3);
  background: linear-gradient(165deg, rgba(9, 18, 33, 0.97), rgba(4, 8, 17, 0.98));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.7), inset 0 0 70px rgba(67, 240, 255, 0.04);
  clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 20px 100%, 0 calc(100% - 20px));
  text-align: center;
  transform: translateY(10px) scale(0.98);
  transition: transform 0.35s cubic-bezier(0.2, 0.9, 0.3, 1.1);
}
.overlay.on .result-card, .overlay.on .rules-card { transform: none; }
.result-kicker { font-family: var(--mono); font-size: 8px; letter-spacing: 0.34em; color: var(--muted); }
.result-card h1, .rules-card h2 {
  margin: 12px 0 8px;
  font-family: var(--mono);
  font-size: clamp(34px, 8vw, 54px);
  line-height: 1;
  letter-spacing: 0.06em;
  background: linear-gradient(180deg, #fff, var(--cyan));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 24px rgba(67, 240, 255, 0.4));
}
.result-card.lose h1 { background: linear-gradient(180deg, #fff, var(--red)); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 0 24px rgba(255, 77, 109, 0.45)); }
.result-card p { margin: 0; font-family: var(--mono); font-size: 11px; letter-spacing: 0.18em; color: #9db4c9; }
.result-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 22px 0;
  padding: 12px 0;
  border-top: 1px solid rgba(105, 190, 230, 0.14);
  border-bottom: 1px solid rgba(105, 190, 230, 0.14);
}
.result-stats div { display: flex; flex-direction: column; gap: 4px; font-family: var(--mono); }
.result-stats span { font-size: 6px; letter-spacing: 0.14em; color: #5e748a; }
.result-stats b { font-size: 16px; color: var(--cyan); }
.result-actions { display: flex; flex-direction: column; gap: 8px; }
.result-actions .ghost-btn { width: 100%; }

.rules-card { text-align: left; }
.rules-card h2 { text-align: center; font-size: clamp(26px, 6vw, 38px); }
.rules-card ul { list-style: none; margin: 20px 0 22px; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.rules-card li { display: grid; grid-template-columns: 74px 1fr; gap: 10px; align-items: start; padding-bottom: 9px; border-bottom: 1px solid rgba(105, 190, 230, 0.1); }
.rules-card li b { font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; color: var(--cyan); padding-top: 2px; }
.rules-card li span { font-size: 10px; line-height: 1.55; color: #a9c2d8; }
.rules-card .action-btn { width: 100%; }

.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  z-index: 80;
  transform: translate(-50%, 20px);
  padding: 9px 16px;
  border: 1px solid rgba(255, 209, 102, 0.5);
  border-radius: 4px;
  background: rgba(8, 14, 28, 0.96);
  color: var(--gold);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  box-shadow: 0 0 26px rgba(255, 209, 102, 0.18);
  white-space: nowrap;
  max-width: calc(100vw - 32px);
  overflow: hidden;
  text-overflow: ellipsis;
}
.toast.on { opacity: 1; transform: translate(-50%, 0); }

.scrim {
  position: fixed;
  inset: 58px 0 0;
  z-index: 35;
  background: rgba(2, 5, 12, 0.6);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s, visibility 0.3s;
}
.scrim.on { opacity: 1; visibility: visible; }

.landing-flash { animation: landingFlash 0.45s ease; }
@keyframes landingFlash {
  0% { filter: brightness(1); }
  20% { filter: brightness(1.45); }
  100% { filter: brightness(1); }
}
.shake { animation: shake 0.35s ease; }
@keyframes shake {
  0%, 100% { transform: translate(0, 0); }
  20% { transform: translate(-3px, 1px); }
  40% { transform: translate(3px, -1px); }
  60% { transform: translate(-2px, -1px); }
  80% { transform: translate(2px, 1px); }
}

/* ───────────────── responsive ───────────────── */

@media (max-width: 1100px) {
  .shell { grid-template-columns: 220px minmax(0, 1fr) 210px; gap: 9px; padding: 9px 10px 0; }
  .brand-text small { display: none; }
  .room-label { display: none; }
}

@media (max-width: 980px) {
  .shell { grid-template-columns: minmax(0, 1fr); padding: 8px 8px 0; }
  .arena-wrap { gap: 4px; }
  .rooms-panel, .feed-panel {
    position: fixed;
    top: 58px;
    bottom: 0;
    z-index: 40;
    width: min(86vw, 330px);
    border-radius: 0;
    background: linear-gradient(180deg, rgba(8, 15, 29, 0.98), rgba(4, 8, 18, 0.98));
    transition: transform 0.32s cubic-bezier(0.2, 0.8, 0.2, 1);
    box-shadow: 0 0 60px rgba(0, 0, 0, 0.6);
    padding-bottom: max(14px, env(safe-area-inset-bottom));
  }
  .rooms-panel { left: 0; transform: translateX(-104%); }
  .feed-panel { right: 0; transform: translateX(104%); }
  .rooms-panel.open, .feed-panel.open { transform: translateX(0); }
  .mobile-only { display: inline-flex; }
  .room-status { margin-left: auto; }
  .net { display: none; }
}

@media (max-width: 700px) {
  .topbar { height: 52px; padding: 0 10px; gap: 8px; }
  .brand-mark { width: 27px; height: 27px; font-size: 15px; }
  .brand-text b { font-size: 11px; letter-spacing: 0.1em; }
  .brand-badge { display: none; }
  .room-status { padding: 5px 8px; gap: 5px; font-size: 8px; }
  .room-status b { font-size: 9px; }
  .room-state { display: none; }
  .icon-btn { min-width: 29px; height: 29px; padding: 0 6px; font-size: 8px; }
  .brand-text { display: none; }
  .scrim { inset: 52px 0 0; }
  .rooms-panel, .feed-panel { top: 52px; }

  .arena { width: min(100%, 66vh); }
  .side { padding: 4px; border-radius: 9px; gap: 4px; }
  .zone-row { gap: 4px; }
  .zone { border-radius: 5px; }
  .zone-label, .zone-index { display: none; }
  .duelist { min-height: 38px; padding: 4px 6px; gap: 6px; }
  .avatar { width: 25px; height: 25px; font-size: 10px; }
  .duelist-top { margin-bottom: 3px; gap: 4px; }
  .duelist-top b { font-size: 8px; }
  .duelist-top span { font-size: 6px; }
  .duelist-top em { display: none; }
  .lp-bar { height: 13px; }
  .lp-bar span { font-size: 8px; left: 6px; }
  .lp-bar small { font-size: 5px; right: 5px; }
  .hand-dots { display: none; }
  .midline { min-height: 36px; padding: 1px 3px; gap: 4px; }
  .turn-chip { padding: 4px 6px; gap: 4px; }
  .turn-chip b { font-size: 7px; }
  .turn-chip small { font-size: 5px; }
  .field-tag { display: none; }
  .ap-wrap { gap: 4px; font-size: 6px; }
  .pip { width: 9px; height: 4px; }
  .controls { min-height: 30px; gap: 8px; }
  .hint { font-size: 7px; letter-spacing: 0.05em; }
  .action-btn { padding: 8px 12px; font-size: 9px; }

  .handbar { height: 138px; padding: 4px 6px max(6px, env(safe-area-inset-bottom)); gap: 6px; }
  .deck-zone { display: none; }
  .hand-side { width: 78px; gap: 5px; }
  .turn-mini { font-size: 6px; }
  .turn-mini b { font-size: 9px; }
  .hand-side .action-btn { padding: 8px 4px; font-size: 8px; letter-spacing: 0.06em; }
  .hand-scroll { padding: 12px 2px 2px; }
  .hand { gap: 5px; }
  .hand-card { width: 74px; }
  .hand-card .card-desc { display: none; }
  .hand-card .card-name { font-size: 8px; }

  .result-card, .rules-card { padding: 24px 18px 20px; }
  .rules-card li { grid-template-columns: 60px 1fr; }
  .toast { bottom: 150px; }
}

@media (max-width: 380px) {
  .hand-card { width: 66px; }
  .hand-side { width: 68px; }
  .handbar { height: 126px; }
  .arena { width: min(100%, 60vh); }
}

@media (max-height: 700px) and (min-width: 701px) {
  .shell { padding-top: 6px; }
  .handbar { height: 128px; }
  .hand-card { width: clamp(66px, 6.4vw, 90px); }
  .arena { width: min(100%, 600px, 60vh); }
  .topbar { height: 50px; }
  .scrim { inset: 50px 0 0; }
}

@media (prefers-reduced-motion: reduce) {
  .bg-grid, .zone::after, .card-frame::before, .card-art::before, .card-art::after, .brand-badge, .scanline { animation: none !important; }
  .card-frame, .card-glyph { animation-duration: 9s; }
  * { scroll-behavior: auto !important; }
}

content.text:
Now game.js. Need careful logic and no syntax errors. Let's plan exact structure.

Constants:
```js
const $ = ...
const state = {...} maybe variable.
const MONSTERS = [...]
const SPELLS = [...]
const ROOMS template.
```

Card object fields: uid, key, name, type, atk, def, cost, glyph, hue, desc, effect?, effectLabel?, rarity.

For board rendering, need `hasAttacked`, `fresh`, `spent`.

Card pool:
Monsters with hues:
- NOVA WYRM 🐉 1800/1200 cost2 hue 185 desc "A serpent of collapsed starlight."
- RONIN-IX 🗡 1600/1000 cost1 hue 200? Use emoji ⚔️ maybe. 
- PRISM GOLEM 🔷 2000/1800 cost2 hue 265
- VOID RAPTOR 🦖 1400/800 cost1 hue 280
- HELIX SERAPH 👁 2200/1600 cost2 hue 45
- EMBER KITSUNE 🦊 1500/900 cost1 hue 20
- CHRONO TITAN ⏳ 2400/2000 cost2 hue 210
- GLITCH HOUND 🐺 1200/700 cost1 hue 150
- AURORA DRAKE 🦅 1900/1400 cost2 hue 170
- SHADOW LYNX 🐈‍⬛ 1700/1100 cost1 hue 250
- QUANTUM MANTIS 🦗 2100/1500 cost2 hue 130
- STEEL PHOENIX 🦚 2000/1700 cost2 hue 320
- SIGNAL WISP 👾 1300/800 cost1 hue 100
- OBSIDIAN OX 🐂 2300/1900 cost2 hue 0

Spells:
- ION BURST ⚡ cost1 dmg 1000 hue 55
- NANO REPAIR ✚ cost1 heal 1200 hue 145
- DATA STREAM ⧉ cost1 draw2 hue 195
- OVERCLOCK ⬢ cost2 buff all +500 hue 120
- PURGE ✖ cost2 destroy strongest enemy hue 350
- PHASE SHIELD ◍ cost1 heal 600 +? Simpler: "PHASE SHIELD" grants +700 DEF? We don't use DEF. Use "GRAVITY WELL" reduce enemy AP by 1? Implement effect. But AI/player. Let's use "EMP FIELD" ⌀ cost1: enemy loses 1 AP next turn. Good.
Effects:
- dmg
- heal
- draw
- buff
- purge
- emp

Deck 18 monsters + 6 spells = 24. Make both decks random. Starter card: pick random monster.

Card instance:
```js
let uidSeq = 0;
function makeCard(def) {
  return {...def, uid: ++uidSeq, hasAttacked:false, fresh:false, spent:false};
}
```
Fresh for deployment.

State:
```js
let state = null;
let roomCode = '';
let soundOn = true;
let bootSkipped = false;
let timers = new Set();
```

Rooms:
```js
const rooms = [
 { id:'yours', name:'YOUR ROOM', host:'YOU', players:2, max:2, ping:8, status:'DUEL', mine:true },
 ...
];
```
roomCode filled after generation. Display own name "YOUR ROOM"; room code. Room `status` values open/duel/full. Map dot class.

Boot create room:
```js
function makeRoomCode(){
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  return '#24-' + Array.from({length:4},...).join('');
}
```
Boot lines dynamic.

Boot implementation:
```js
const boot = $('#boot'), bootLog=..., bootBar=..., bootPct=...;
let bootDone=false;
function startBoot(){
  roomCode = makeRoomCode();
  $('#roomCode').textContent=roomCode;
  const lines = [
    ['INITIALIZING NEXUS CORE','OK'],
    ['CREATING PRIVATE ROOM ' + roomCode,'OK'],
    ['AUTO-JOINING YOUR ROOM','OK'],
    ['4 OPEN ROOMS DISCOVERED','OK'],
    ['KAI CONNECTED TO ' + roomCode,'LINK'],
    ['SYNCING 24-ZONE FIELD','OK'],
    ['DUEL START','GO'],
  ];
  let i=0;
  const step=()=>{
    if(bootDone) return;
    if(i<lines.length){
      addBootLine(lines[i][0],lines[i][1]);
      i++;
      const pct=Math.min(100, Math.round(i/lines.length*100));
      ...
      setTimeout(step, bootSkipped?20:260);
    } else {
      setTimeout(finishBoot,bootSkipped?60:420);
    }
  };
  step();
  boot.addEventListener('click',()=>{ bootSkipped=true; });
}
```
Potential click skip only sets flag, steps continue every 20ms; fine. Could directly finish after a tick. Keep.

finishBoot once:
```js
function finishBoot(){
  if(bootDone) return; bootDone=true;
  boot.classList.add('gone');
  app.classList.add('on'); app.ariaHidden=false;
  setTimeout(()=>{ boot.remove(); }, 700);
  initRoomAndDuel();
}
```

init:
- render rooms, start intervals.
- `newDuel(true)` and render.
- log events.

`log()` needs state. For boot messages after app visible, state exists.

Duel:
```js
function createSide(name){
  return {name, lp:8000, maxLp:8000, deck:shuffle(buildDeck()), hand:[], front:Array(6).fill(null), back:Array(6).fill(null), ap:3, maxAp:3, apPenalty:0};
}
function newDuel(){
  const id = ++duelSeq;
  state = { id, over:false, result:null, turn:'player', turnNo:1, player:createSide('YOU'), enemy:createSide('KAI'), selectedHand:null, selectedUnit:null, busy:false, stats:{cards:0, damage:0, kills:0}, feed:[], start:Date.now() };
  uidSeq = ... no need reset
  $('#overlay').classList.remove('on');
  $('#rematchMini').hidden=true;
  // opening
  drawCards(state.player,4);
  drawCards(state.enemy,4);
  const starterP = takeStarter(state.player);
  const starterE = takeStarter(state.enemy);
  if(starterP){ state.player.front[2]=starterP; starterP.fresh=true; }
  if(starterE){ state.enemy.front[3]=starterE; starterE.fresh=true; }
  startPlayerTurn(true, id);
  setRoomState('IN DUEL');
  clearFeed();
  feedLog('Room '+roomCode+' // duel initialized','sys');
  if(starterP) feedLog('YOU deployed '+starterP.name,'you');
  if(starterE) feedLog('KAI deployed '+starterE.name,'enemy');
  feedLog('YOUR TURN // 3 AP','you');
  toast? no.
}
```
Order: startPlayerTurn draws 1, render. Then logs. Fine.

`startPlayerTurn(opening, id)`:
```js
if(state.over) return;
