function drawCards(side, n){
  const drawn=[];
  for(let i=0;i<n;i++){
    const c = side.deck.pop();
    if(!c) break;
    c.fresh=true;
    if(side.hand.length<8) side.hand.push(c); else { side.deck.unshift(c); break; } // no room; put back
    drawn.push(c);
  }
  return drawn;
}
