async function handlePlayerPlay(card, row, index) {
  const isSpell = card.type === 'spell';
  if (isSpell) {
    state.busy = true;
    syncHUD();
  }

  const ok = await playCard('player', card, row, index);
  if (isSpell) state.busy = false;

