Auto-player algorithm:
```js
() => (async () => {
  const sleep = ms => new Promise(r=>setTimeout(r,ms));
  const q=(s)=>document.querySelector(s), qa=(s)=>[...document.querySelectorAll(s)];
  const ap=()=>+q('#apCount').textContent;
  const turn=()=>q('#turnText').textContent;
  const over=()=>q('#overlay').classList.contains('on');
  let turns=0;
  while(!over() && turns<40){
    if(turn()!=='YOUR TURN'){ await sleep(400); continue; }
    // play best affordable card if there is a legal zone
    let acted=false;
    for(const h of qa('.hand-card')){
      const cost=+h.querySelector('.card-cost').textContent;
      if(cost<=ap()){
        h.click(); await sleep(100);
        const z=q('#playerFront .zone.playable')||q('#playerBack .zone.playable');
        if(z){ z.click(); await sleep(500); acted=true; break; }
        h.click(); await sleep(50);
      }
    }
    // attack loop
    while(turn()==='YOUR TURN' && ap()>0 && !over()){
      const units=qa('#playerFront .zone.filled').filter(z=>!z.querySelector('.card').classList.contains('attacked'));
      if(!units.length) break;
      const atk=z=>+((z.querySelector('.card-stat.atk').textContent.match(/\d+/)||[0])[0]);
      units.sort((a,b)=>atk(b)-atk(a));
      units[0].click(); await sleep(120);
      const targets=qa('#enemyFront .zone.targetable');
      if(targets.length){
        targets.sort((a,b)=>atk(a)-atk(b));
        const mine=atk(units[0]);
        const t=targets.find(z=>atk(z)<mine);
        if(t){ t.click(); await sleep(800); acted=true; continue; }
        document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}));
        break;
      } else {
        q('#enemyDuelist').click(); await sleep(800); acted=true; continue;
      }
    }
    if(over()) break;
    if(turn()==='YOUR TURN'){ q('#endTurnBtn').click(); turns++; }
    await sleep(800);
  }
  return {turns, over:over(), title:q('#resultTitle').textContent, lp:[q('#playerLP').textContent,q('#enemyLP').textContent], log:[...qa('.feed-item p')].slice(-8).map(p=>p.textContent)};
})()
```
